<?php
declare(strict_types=1); require dirname(__DIR__,2).'/includes/bootstrap.php'; require_admin(); verify_csrf($_SERVER['HTTP_X_CSRF_TOKEN']??null); $payload=request_json();
try{$repo=new App\Repositories\TemplateRepository(db(),current_user_id(),is_super_admin());$source=$repo->currentConfiguration((int)($payload['id']??0));if(!$source)throw new InvalidArgumentException('القالب غير موجود.');$idMap=[];foreach($source['groups'] as $g)$idMap[(int)$g['id']]=$g['group_key'];$groups=[];foreach($source['groups'] as $g)$groups[]=['group_key'=>$g['group_key'],'name'=>$g['name'],'parent_key'=>$g['parent_id']?($idMap[(int)$g['parent_id']]??null):null,'sort_order'=>$g['sort_order'],'text_direction'=>$g['text_direction'],'display_direction'=>$g['display_direction']];$columns=[];foreach($source['columns'] as $c){$c['header_group_key']=$c['header_group_id']?($idMap[(int)$c['header_group_id']]??null):null;$columns[]=$c;}$id=(new App\Services\TemplateService(db(),$repo))->save(['name'=>$source['name'].' - نسخة','description'=>$source['description'],'groups'=>$groups,'columns'=>$columns,'settings'=>$source['settings']],current_user_id());json_response(['ok'=>true,'id'=>$id]);}catch(Throwable $e){json_response(['ok'=>false,'message'=>$e->getMessage()],422);}